-- Gold Query
SELECT t2.name FROM Match AS t1 INNER JOIN League AS t2 ON t1.league_id = t2.id WHERE t1.season = '2015/2016' GROUP BY t2.name ORDER BY SUM(t1.home_team_goal + t1.away_team_goal) DESC, t2.name NULLS LAST LIMIT 1;

/*
Gold Result:
('2015/2016',)
*/

